import{_ as a,o as l,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Days NYC 2023: Welcome and Community Update","description":"","frontmatter":{"title":"Ceph Days NYC 2023: Welcome and Community Update","date":"2023-05-17T00:00:00.000Z","updated":"2023-05-17T00:00:00.000Z","tags":["Ceph","分布式存储","社区更新","会议纪要","Bloomberg"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Days_NYC_2023_-_Welcome_and_Community_Update.md","filePath":"posts/2023/Ceph_Days_NYC_2023_-_Welcome_and_Community_Update.md","lastUpdated":1780459816000}'),i={name:"posts/2023/Ceph_Days_NYC_2023_-_Welcome_and_Community_Update.md"};function r(h,e,d,n,_,s){return l(),o("div",null,[...e[0]||(e[0]=[t('<p>Ceph Days NYC 2023会议在Bloomberg办公室举行，由Matthew Leonard主持。以下是对会议内容的改进总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><ul><li>会议名称：Ceph Days New York</li><li>地点：Bloomberg办公室，纽约</li><li>主持人：Matthew Leonard</li></ul><h3 id="会议欢迎与感谢" tabindex="-1">会议欢迎与感谢 <a class="header-anchor" href="#会议欢迎与感谢" aria-label="Permalink to &quot;会议欢迎与感谢&quot;">​</a></h3><ul><li>主持人Matthew Leonard对与会者的到来表示欢迎，并对Bloomberg团队、SEF董事会成员及志愿者的辛勤工作表示感谢。</li></ul><h3 id="会议背景与目的" tabindex="-1">会议背景与目的 <a class="header-anchor" href="#会议背景与目的" aria-label="Permalink to &quot;会议背景与目的&quot;">​</a></h3><ul><li>Matthew Leonard介绍了Bloomberg与Ceph的关系，指出Bloomberg的存储工程团队管理着公司的存储基础设施，并使用Ceph作为下一代云平台和S3平台的基础。</li><li>Bloomberg已经参与Ceph社区多年，主要通过报告问题和验证代码修复来贡献。</li></ul><h3 id="项目与贡献" tabindex="-1">项目与贡献 <a class="header-anchor" href="#项目与贡献" aria-label="Permalink to &quot;项目与贡献&quot;">​</a></h3><ul><li>Bloomberg正在开发一些与Ceph生态系统相关的项目，包括实时分布式第7层服务质量（QoS）堆栈和Ceph的大规模遥测收集。</li><li>尽管Bloomberg尚未直接贡献主要功能，但他们计划在未来更积极地参与社区。</li></ul><h3 id="社区与未来展望" tabindex="-1">社区与未来展望 <a class="header-anchor" href="#社区与未来展望" aria-label="Permalink to &quot;社区与未来展望&quot;">​</a></h3><ul><li>Matthew Leonard强调了社区在Ceph项目中的重要性，并鼓励更多人参与和贡献。</li><li>提到了即将在阿姆斯特丹、印度、温哥华和首尔等地举办的Ceph相关活动。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><ul><li>Matthew Leonard再次感谢所有参与者和支持者，并期待未来再次相聚。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>鼓励社区成员积极参与即将到来的Ceph活动，并考虑提交演讲。</li><li>Bloomberg计划在未来更积极地参与Ceph社区，特别是在代码贡献和功能开发方面。</li></ul><p>此次会议不仅展示了Bloomberg在Ceph领域的应用和贡献，也强调了社区合作的重要性，并为未来的合作和活动奠定了基础。</p>',16)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
